import{_ as o,o as a,c as t,a2 as d}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),r={name:"guide/troubleshooting.md"};function i(n,e,c,s,u,l){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="创建实例应该用-create-还是-use" tabindex="-1">创建实例应该用 create 还是 use？ <a class="header-anchor" href="#创建实例应该用-create-还是-use" aria-label="Permalink to &quot;创建实例应该用 create 还是 use？&quot;">​</a></h2><p>Vue 页面内优先使用 <code>usePrintStudio()</code>，实例随 Vue 作用域自动清理；业务模块需要自行管理存活期时用 <code>createPrintStudio()</code>。二者返回同一套实例 API，差异在创建方式与生命周期归属，见<a href="./introduction.html#创建方式">简介 · 创建方式</a>。已有模板只需输出时用 <code>createPrintRenderer</code>。</p><h2 id="安装时找不到-print-studio-包" tabindex="-1">安装时找不到 print-studio 包 <a class="header-anchor" href="#安装时找不到-print-studio-包" aria-label="Permalink to &quot;安装时找不到 print-studio 包&quot;">​</a></h2><p>确认包源已发布该包（<code>pnpm view @printstack/print-studio version</code> 可查），安装步骤见<a href="./installation.html">安装与项目集成</a>。</p><h2 id="设计器空白或高度为零" tabindex="-1">设计器空白或高度为零 <a class="header-anchor" href="#设计器空白或高度为零" aria-label="Permalink to &quot;设计器空白或高度为零&quot;">​</a></h2><p>确认容器有明确高度，grid/flex 子项允许收缩，并检查启动错误。先使用<a href="./getting-started.html">快速开始</a>的布局。默认 Vite 模板的居中和宽度样式可按业务布局移除。</p><h2 id="命令式挂载提示-already-mounted-或-ready-被拒绝" tabindex="-1">命令式挂载提示 already mounted 或 ready 被拒绝 <a class="header-anchor" href="#命令式挂载提示-already-mounted-或-ready-被拒绝" aria-label="Permalink to &quot;命令式挂载提示 already mounted 或 ready 被拒绝&quot;">​</a></h2><p>同一个容器或实例同时只能挂载一个设计器，先调用 <code>studio.unmount()</code> 或旧句柄的 <code>unmount()</code> 再重新挂载。<code>mount()</code> / <code>ready</code> 在启动失败时拒绝，初始化完成前卸载会产生 <code>AbortError</code>；宿主应处理拒绝并清理。外部 <code>studio</code> 在卸载后可以复用，入口自建的内部实例随卸载销毁，见 <a href="./../reference/vue-designer.html#mountprintdesigner-低阶入口">studio.mount() 与 mountPrintDesigner()</a>。</p><h2 id="按钮修改了文档-但画布没变化" tabindex="-1">按钮修改了文档，但画布没变化 <a class="header-anchor" href="#按钮修改了文档-但画布没变化" aria-label="Permalink to &quot;按钮修改了文档，但画布没变化&quot;">​</a></h2><p>确认按钮和 <code>&lt;PrintDesigner :studio=&quot;studio&quot; /&gt;</code> 使用同一实例。兄弟组件分别调用 <code>usePrintStudio()</code> 通常会创建各自的实例。不要修改 <code>element.data.props</code> 或 <code>document.data</code> 快照来编辑状态，应使用实例方法。</p><h2 id="useprintstudio-的-onsave-或-initialdocument-没生效" tabindex="-1">usePrintStudio 的 onSave 或 initialDocument 没生效 <a class="header-anchor" href="#useprintstudio-的-onsave-或-initialdocument-没生效" aria-label="Permalink to &quot;usePrintStudio 的 onSave 或 initialDocument 没生效&quot;">​</a></h2><p>检查是否复用了显式或祖先注入的上下文。复用时不重新应用创建选项，配置应放在上下文创建处。替换文档使用 <code>studio.document.load/loadJson</code>，见 <a href="./../reference/vue-designer.html#useprintstudio">usePrintStudio()</a>。</p><h2 id="保存失败-或者刷新后内容丢失" tabindex="-1">保存失败，或者刷新后内容丢失 <a class="header-anchor" href="#保存失败-或者刷新后内容丢失" aria-label="Permalink to &quot;保存失败，或者刷新后内容丢失&quot;">​</a></h2><p><code>document.save()</code> 必须配置 <code>onSave</code>。<code>storage</code> 仅管理本地草稿，默认关闭；<code>export.json()</code> 只返回字符串。快速开始是手动保存再手动恢复，服务器保存示例需要替换接口。浏览器存储也可能失败，应接入统一错误处理。</p><h2 id="绑定仍显示表达式或输出为空" tabindex="-1">绑定仍显示表达式或输出为空 <a class="header-anchor" href="#绑定仍显示表达式或输出为空" aria-label="Permalink to &quot;绑定仍显示表达式或输出为空&quot;">​</a></h2><p>画布把绑定变量渲染为标签（不含花括号）；设计时预览使用 <code>sampleData</code> 与 <code>settings.previewWithData</code>。实际输出把数据传给 <code>studio.preview(input)</code> 等方法，确认字段路径匹配。</p><p>字符串表达式用双花括号，表格 <code>bindings.rows</code> 和循环 <code>collection</code> 用裸路径。省略输入会使用示例数据；显式 <code>{}</code> 表示空输入，不自动合并示例。检查 <code>warnings</code>，见<a href="./../reference/data-binding.html">数据源与数据绑定</a>。</p><h2 id="pdf、字体、图片或分页与预期不同" tabindex="-1">PDF、字体、图片或分页与预期不同 <a class="header-anchor" href="#pdf、字体、图片或分页与预期不同" aria-label="Permalink to &quot;PDF、字体、图片或分页与预期不同&quot;">​</a></h2><p>输出需要浏览器 DOM / Canvas 和可读取的字体、图片。输出 API 会在布局前等待字体，预览和打印还会等待 iframe 的字体、图片就绪。检查元素的字族、字重与 <code>rendering.fonts</code> 或 <code>@font-face</code> 是否匹配，字体文件和远程图片是否允许跨域读取、是否满足 CSP。跨域样式表无法读取时，改用 <code>rendering.fonts</code> 显式提供字体 URL，见<a href="./../reference/output.html#字体与资源">字体与资源</a>。</p><p>字体失败会以 <code>render.font-load-failed</code> 拒绝输出；资源任务超时为 <code>render.resource-timeout</code>，通过输出的 <code>execution.timeoutMs</code> 或预览、打印的 <code>options.timeoutMs</code> 调整，默认 60000ms。仅增大 <code>workerTimeoutMs</code> 不会改变整体资源任务超时。PDF 与浏览器打印走不同输出路径，需要分别验证；打印对话框的纸张、缩放、边距和背景选项也影响结果。</p><p>表格自动分页需启用 <code>heightMode: &#39;auto&#39;</code> 与 <code>pagination.crossPage</code>；长文本自适应高度不等于任意长文本自动拆页，见<a href="./../reference/element-text.html">元素配置</a>和<a href="./../reference/template-page.html">布局</a>。</p><h2 id="输出成功是否代表已经打印" tabindex="-1">输出成功是否代表已经打印？ <a class="header-anchor" href="#输出成功是否代表已经打印" aria-label="Permalink to &quot;输出成功是否代表已经打印？&quot;">​</a></h2><p><code>print()</code> 返回表示调用流程完成（打印对话框已调起），无法确认用户是否取消或设备是否出纸。不要仅据此更新「已打印」业务状态，见 <a href="./../reference/output.html#print">print()</a>。</p><h2 id="返回了-disposed-错误" tabindex="-1">返回了 disposed 错误 <a class="header-anchor" href="#返回了-disposed-错误" aria-label="Permalink to &quot;返回了 disposed 错误&quot;">​</a></h2><p>实例或借用上下文已被销毁。<code>usePrintStudio()</code> 返回的实例随 Vue 作用域销毁释放，不要继续在模块中持有并使用。跨路由保留实例用业务模块创建的 <code>createPrintStudio()</code>，由持有方最终清理；加载另一份文档后重新查询句柄。</p>',26)])])}const m=o(r,[["render",i]]);export{p as __pageData,m as default};
